public class RagEvaluator
{
    private readonly IChatClient _ragSystem;   // System under test
    private readonly IChatClient _judge;        // GPT-4-turbo for judging
    private readonly IVectorSearchService _retriever;

    public async Task<RagEvaluationResult> EvaluateAsync(
        string question, string groundTruth, CancellationToken ct = default)
    {
        // Step 1: Run the RAG pipeline
        var retrievedContext = await _retriever.SearchAsync(question, topK: 5, ct);
        var contextText = string.Join("\n---\n", retrievedContext.Select(d => d.Content));
        var prompt = $"Question: {question}\n\nContext:\n{contextText}";
        var answer = await _ragSystem.CompleteAsync(prompt, new ChatOptions
        {
            Temperature = 0.1f,
            MaxOutputTokenCount = 500
        }, ct);

        // Step 2: Judge faithfulness — does the answer match the context?
        var faithfulnessScore = await JudgeFaithfulnessAsync(question, contextText, answer.Text, ct);

        // Step 3: Judge answer relevance — is the answer relevant to the question?
        var relevanceScore = await JudgeRelevanceAsync(question, answer.Text, ct);

        // Step 4: Context precision — are retrieved docs relevant?
        var precisionScore = await JudgeContextPrecisionAsync(question, retrievedContext, ct);

        // Step 5: Compare to ground truth (if available)
        var accuracyScore = await JudgeFactualAccuracyAsync(groundTruth, answer.Text, ct);

        return new RagEvaluationResult
        {
            Question = question,
            GeneratedAnswer = answer.Text,
            Faithfulness = faithfulnessScore,
            AnswerRelevance = relevanceScore,
            ContextPrecision = precisionScore,
            Factuality = accuracyScore,
            OverallScore = (faithfulnessScore + relevanceScore + precisionScore + accuracyScore) / 4
        };
    }

    private async Task<double> JudgeFaithfulnessAsync(
        string question, string context, string answer, CancellationToken ct)
    {
        var judgePrompt = $$
"""Evaluate whether the answer is faithful to the provided context. Does every claim
in the answer have supporting evidence in the context?

Score: 1.0 = perfectly faithful, 0.0 = entirely hallucinated.
Format: Just output a number 0-1.

Question: {{question}}
Context: {{context}}
Answer: {{answer}}
""";

        var response = await _judge.CompleteAsync(judgePrompt, cancellationToken: ct);
        return ParseScore(response.Text);
    }
}

public enum RagFailureMode
{
    Successful,          // Answer is correct and grounded
    NoContext,           // Retriever returned no relevant docs
    WrongContext,        // Retrieved wrong docs, answer not grounded
    ContextIgnored,      // LLM ignored the provided context
    Hallucination,       // Answer not supported by any context
    FactualError,        // Answer contradicts known facts
    IncompleteAnswer     // Partial answer, missing key info
}

public class FailureAnalyzer
{
    private readonly IChatClient _classifier;

    public async Task<RagFailureMode> ClassifyFailureAsync(
        string question, List<DocumentChunk> context, string answer, string groundTruth)
    {
        var hasContext = context.Any();
        var contextRelevant = await IsContextRelevantAsync(question, context);
        var answerInContext = await IsAnswerSupportedAsync(answer, context);
        var answerCorrect = await IsAnswerCorrectAsync(answer, groundTruth);

        if (!hasContext || !contextRelevant)
            return RagFailureMode.NoContext;
        if (!answerInContext)
            return RagFailureMode.Hallucination;
        if (answerCorrect && answerInContext)
            return RagFailureMode.Successful;
        if (!answerCorrect)
            return RagFailureMode.FactualError;

        return RagFailureMode.IncompleteAnswer;
    }
}
